import {requestId as requestUUID} from './request-id.js?v=58ef88b53202';
import {participation,participationBar,openParticipation,refreshParticipationBanners} from './participation.js?v=1c030d58e4db';
export const TIPS_ORIGIN='https://manor-feedback.tacocat070116.chatgpt.site';
export const TIP_STATUSES={pending:'검토 대기',approved:'공개 중',needs_changes:'보완 요청',rejected:'반려',hidden:'비공개'};
export const tipEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=tipEscape;
const date=value=>value?new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Seoul'}).format(new Date(value)):'';
const lock='<svg class="tip-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/></svg>';
const check='<svg class="tip-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>';
function pair(t,characters){return `<div class="tip-pair">${[t.ownId,t.opponentId].map((id,i)=>{const c=characters[id];return `${i?'<span class="tip-pair-arrow" aria-hidden="true">→</span>':''}<a href="#v=character&c=${e(id)}&tab=tips">${c?.portrait?`<img src="${e(c.portrait)}" alt="" width="32" height="32" loading="lazy">`:''}<span>${e(c?.name||'캐릭터')}</span></a>`;}).join('')}</div>`;}
export function tipCard(t,characters,{mine=false}={}){
 return `<article class="tip-card">${pair(t,characters)}<div class="tip-author"><strong>${e(t.displayName)}</strong>${t.verifiedAt?`<span class="tip-verified">${check}티어 확인</span>`:''}${mine?`<span class="tip-status tip-status-${e(t.status)}">${e(TIP_STATUSES[t.status])}</span>`:''}</div>${t.verifiedAt?`<p class="tip-rank">${e(t.verifiedTier)} · ${e(t.verifiedSeason)} <span>${e(date(t.verifiedAt))} 확인</span></p>`:mine?`<p class="tip-rank">신청 ${e(t.claimedTier)} · ${e(t.season)}</p>`:''}<p class="tip-copy">${e(t.body)}</p>${t.context?`<div class="tip-context"><span>적용 조건</span><p>${e(t.context)}</p></div>`:''}<div class="tip-card-footer"><time datetime="${new Date(t.updatedAt).toISOString()}">${e(date(t.updatedAt))} ${mine?'제출·수정':'갱신'}</time>${mine?`<div><button type="button" class="tip-text-button" data-tip="edit" data-id="${e(t.id)}">수정</button><button type="button" class="tip-text-button" data-tip="delete" data-id="${e(t.id)}">삭제</button></div>`:''}</div>${mine&&t.reviewMessage?`<div class="tip-review-message"><strong>운영자 검토 의견</strong><p>${e(t.reviewMessage)}</p></div>`:''}</article>`;
}
export function tipSubmissionForm({characters,ownId,opponentId='',tip=null,origin=TIPS_ORIGIN}){
 const own=characters[tip?.ownId||ownId],opponent=tip?.opponentId||opponentId;
 const options=Object.values(characters).filter(c=>c.side!==own.side).sort((a,b)=>a.name.localeCompare(b.name,'ko')).map(c=>`<option value="${e(c.id)}" ${c.id===opponent?'selected':''}>${e(c.name)}</option>`).join('');
 return `<form class="tip-form" data-tip-form="submission" method="post" action="${e(origin)}/api/tips"><div class="tip-form-heading"><div><span class="eyebrow">PLAYER NOTES</span><h3>${tip?'상대법 수정':'내 경험으로 쓰는 상대법'}</h3><p>${e(own.name)} 플레이 경험을 바탕으로 상대법을 남겨주세요.</p></div><button type="button" class="tip-text-button" data-tip="cancel">닫기</button></div><input type="hidden" name="ownId" value="${e(own.id)}"><div class="tip-form-grid"><label>상대 캐릭터<select name="opponentId" required><option value="">상대를 선택하세요</option>${options}</select></label><label>공개 이름<input name="displayName" minlength="2" maxlength="24" value="${e(tip?.displayName)}" placeholder="공개할 별명" required autocomplete="off"></label><label>${e(own.side)} 티어<input name="claimedTier" maxlength="40" value="${e(tip?.claimedTier)}" placeholder="예: 7단 · 현재 티어" required></label><label>해당 시즌<input name="season" maxlength="24" value="${e(tip?.season)}" placeholder="예: S + 시즌 번호" required></label></div><label>상대법<textarea name="body" minlength="20" maxlength="3000" rows="7" placeholder="어떤 상황에서 어떻게 대응하는지, 실패하기 쉬운 점까지 구체적으로 적어주세요." required>${e(tip?.body)}</textarea></label><label>적용 조건 <span class="tip-optional">선택</span><textarea name="context" maxlength="300" rows="2" placeholder="맵, 인격, 시작 위치 등 판단에 영향을 주는 조건">${e(tip?.context)}</textarea></label><fieldset class="tip-private"><legend>${lock}운영자에게만 전달되는 검토정보</legend><p>글과 티어를 확인하는 용도입니다. 서버·UID·참고사항은 공개되지 않습니다.</p>${tip?'<p>기존 검토정보는 보관되어 있습니다. 서버·UID를 변경할 때만 두 항목을 다시 입력하세요.</p>':''}<div class="tip-form-grid"><label>서버<select name="server" ${tip?'':'required'}><option value="">${tip?'기존 정보 유지':'서버 선택'}</option><option value="asia">아시아</option><option value="naeu">NA/EU</option></select></label><label>게임 UID<input name="uid" type="text" inputmode="numeric" pattern="[0-9]{3,20}" minlength="3" maxlength="20" autocomplete="off" spellcheck="false" placeholder="숫자 UID" ${tip?'':'required'}></label></div><label>검토 참고사항 <span class="tip-optional">선택</span><textarea name="verificationNote" maxlength="1000" rows="3" placeholder="캐릭터 순위, 랭킹 위치, 본인 확인에 참고할 내용. 보완 요청을 받았다면 여기에 답변해 주세요."></textarea></label></fieldset><p class="tip-guide">작성 기록은 서버에 보관됩니다. 개인 복구 코드를 따로 저장하면 다른 브라우저에서도 내 글과 운영자 검토 의견을 확인할 수 있습니다.</p><label class="tip-consent"><input type="checkbox" name="privacyConsent" required><span>운영자의 티어·작성자 확인을 위해 검토정보를 제출합니다. 승인되면 이름·상대법·확인 티어·시즌·확인일이 공개되며, 글을 삭제하면 검토정보도 삭제됩니다.</span></label><div class="tip-form-bottom"><p>${tip?'수정한 글은 다시 검토하며, 승인 전까지 공개 목록에서 내려갑니다.':'운영자가 상위 티어와 캐릭터 경험을 검토한 뒤 공개합니다.'}</p><button class="btn primary" type="submit">${tip?'수정 후 다시 제출':'검토 요청하기'}</button></div></form>`;
}
const token=()=>participation.read();
export function mountMatchupTips(root,{characters,ownId,opponentId='',origin=TIPS_ORIGIN}={}){
 let alive=true,busy=false,version=0,mode='public',opponent=opponentId,items=[],nextPage=null,editing=null,requestId=requestUUID();
 let authorAtOpen=token();
 const controllers=new Set();
 const notice=(message,error=false)=>{const node=root.querySelector('.tip-notice');if(node){node.textContent=message;node.hidden=!message;node.classList.toggle('is-error',error);}};
 const frame=html=>{if(alive)root.innerHTML=`<section class="matchup-tips"><div class="tip-notice" role="status" aria-live="polite" hidden></div>${html}</section>`;};
 const header=()=>`<div class="tip-heading"><div><div class="eyebrow">PLAYER EXPERIENCE</div><h2>유저 상대법</h2><p>운영자가 티어와 작성 내용을 검토한 플레이어의 경험입니다.</p></div><button class="btn primary small" type="button" data-tip="compose">상대법 남기기</button></div><div class="tip-toolbar"><div class="tip-tabs" role="group" aria-label="상대법 보기"><button type="button" data-tip="public" aria-pressed="${mode==='public'}">검토된 상대법</button><button type="button" data-tip="mine" aria-pressed="${mode==='mine'}">내 제출 내역</button></div>${mode==='public'&&!opponentId?`<label><span class="visually-hidden">상대 캐릭터 필터</span><select data-tip-filter="opponent"><option value="">모든 상대</option>${Object.values(characters).filter(c=>c.side!==characters[ownId].side).sort((a,b)=>a.name.localeCompare(b.name,'ko')).map(c=>`<option value="${e(c.id)}" ${c.id===opponent?'selected':''}>${e(c.name)}</option>`).join('')}</select></label>`:''}</div>`;
 async function api(path,{method='GET',body,authenticated=false,authorToken,identityRetry=true}={}){
  const requestToken=authenticated?(authorToken??token()):'';
  const controller=new AbortController();controllers.add(controller);const timeout=setTimeout(()=>controller.abort(),15000),headers={};
  if(body!==undefined)headers['Content-Type']='application/json';if(requestToken)headers.Authorization='Bearer '+requestToken;
  try{const response=await fetch(origin+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'omit',cache:'no-store',signal:controller.signal});let result;try{result=await response.json();}catch{throw Error('서버 응답을 확인하지 못했습니다. 잠시 후 다시 시도해 주세요.');}if(!response.ok){if(result.code==='visitor_invalid')await participation.invalidate(requestToken);throw Error(result.error||'요청을 처리하지 못했습니다.');}if(authenticated&&method==='GET'&&identityRetry&&requestToken!==token())return api(path,{authenticated,identityRetry:false});return result;}catch(error){if(error.name==='AbortError')throw Error('연결이 지연되고 있습니다. 다시 시도해 주세요.');if(error instanceof TypeError)throw Error('서버에 연결하지 못했습니다. 네트워크 상태를 확인한 뒤 다시 시도해 주세요.');throw error;}finally{clearTimeout(timeout);controllers.delete(controller);}
 }
 async function ensureVisitor(){if(authorAtOpen&&authorAtOpen!==token())throw Error('다른 창에서 연결된 기록이 바뀌었습니다. 입력한 내용은 유지됩니다. 원래 기록으로 다시 연결하거나 내용을 보관한 뒤 새로고침해 주세요.');const identity=await participation.ensure(()=>api('/api/feedback/visitors',{method:'POST',body:{}}));authorAtOpen=identity;refreshParticipationBanners();return identity;}
 function listView(data,append){
  items=append?[...items,...data.tips.filter(t=>!items.some(x=>x.id===t.id))]:data.tips;nextPage=data.nextPage;
  frame(`${header()}${participationBar()}<p class="tip-list-caption">${mode==='mine'?'연결된 기록으로 제출한 상대법':e(characters[ownId].name)+' 관점'} · ${data.total}개</p><div class="tip-list">${items.length?items.map(t=>tipCard(t,characters,{mine:mode==='mine'})).join(''):`<div class="tip-empty"><h3>${mode==='mine'?'아직 제출한 상대법이 없습니다.':'아직 검토를 마친 상대법이 없습니다.'}</h3><p>${mode==='mine'?'내가 제출한 글의 상태와 보완 요청이 여기에 표시됩니다. 다른 브라우저에서 쓴 글은 개인 복구 코드로 연결해 주세요.':'직접 겪은 대응법을 남겨주세요. 검토가 끝나면 이곳에서 함께 볼 수 있습니다.'}</p><button class="btn small" type="button" data-tip="compose">상대법 남기기</button></div>`}</div>${nextPage!==null?'<button class="btn tip-more" type="button" data-tip="more">더 보기</button>':''}<div class="tip-guide"><p>${lock}서버와 UID는 운영자만 확인합니다. 티어 표시는 검토한 시즌·확인일 기준이며, 상대법의 적용 조건을 함께 살펴보세요.</p>${mode==='mine'?'<p>작성 기록은 서버에 보관됩니다. 개인 복구 코드를 따로 저장하면 다른 브라우저에서도 내 글과 운영자 검토 의견을 확인할 수 있습니다.</p>':''}</div>`);
 }
 async function load(append=false){
  const current=++version;if(!append)frame(`${header()}<div class="tip-empty" role="status"><span class="loading-orbit" aria-hidden="true"></span><p>상대법을 불러오고 있습니다.</p></div>`);
  if(mode==='mine'&&!token()){listView({tips:[],total:0,nextPage:null},false);return;}
  const query=new URLSearchParams({page:String(append?nextPage:0)});if(mode==='public'){query.set('own',ownId);if(opponent)query.set('opponent',opponent);}
  try{const data=await api('/api/tips'+(mode==='mine'?'/mine':'')+'?'+query,{authenticated:mode==='mine'});if(alive&&current===version)listView(data,append);}catch(error){if(alive&&current===version){frame(`${header()}<div class="tip-empty"><h3>상대법을 불러오지 못했습니다.</h3><p>${e(error.message)}</p><button class="btn small" type="button" data-tip="reload">다시 시도</button></div>`);}}
 }
 function compose(tip=null){++version;editing=tip;requestId=requestUUID();frame(participationBar()+tipSubmissionForm({characters,ownId,opponentId:opponent,tip,origin}));root.querySelector('[name="'+(tip?'body':'opponentId')+'"]')?.focus();}
 async function click(event){
  const recovery=event.target.closest('[data-participation]');
  if(recovery?.dataset.participation==='open'){event.preventDefault();if(busy)return;openParticipation({origin,mode:recovery.dataset.participationView,beforeSwitch:()=>!root.querySelector('[data-tip-form="submission"]')||confirm('입력 중인 내용이 있습니다. 기록을 전환하고 목록을 다시 불러올까요?'),onConnected:()=>{authorAtOpen=token();controllers.forEach(c=>c.abort());mode='mine';load();}});return;}
  const b=event.target.closest('[data-tip]');if(!b||!root.contains(b))return;event.preventDefault();if(busy)return;
  const action=b.dataset.tip;if(action==='compose'){compose();return;}if(action==='edit'){const item=items.find(t=>t.id===b.dataset.id);if(item&&mode==='mine')compose(item);return;}
  if(action==='cancel'||action==='reload'){load();return;}if(action==='public'||action==='mine'){mode=action;load();return;}
  if(action==='more'){busy=true;b.disabled=true;try{await load(true);}finally{busy=false;if(b.isConnected)b.disabled=false;}return;}
  if(action==='delete'&&mode==='mine'&&confirm('상대법과 비공개 검토정보를 삭제할까요? 삭제 후에는 되돌릴 수 없습니다.')){busy=true;b.disabled=true;try{await api('/api/tips/'+b.dataset.id,{method:'DELETE',authenticated:true});if(alive){await load();notice('상대법과 검토정보를 삭제했습니다.');}}catch(error){if(alive)notice(error.message,true);}finally{busy=false;if(b.isConnected)b.disabled=false;}}
 }
 async function submit(event){
  const form=event.target.closest('[data-tip-form="submission"]');if(!form||!root.contains(form))return;event.preventDefault();if(busy||!form.reportValidity())return;
  const data=new FormData(form),body=Object.fromEntries(['ownId','opponentId','displayName','claimedTier','season','body','context'].map(k=>[k,String(data.get(k)||'')]));
  const server=String(data.get('server')||''),uid=String(data.get('uid')||'').trim(),note=String(data.get('verificationNote')||'').trim();
  if(server||uid||!editing){body.server=server;body.uid=uid;}if(note||!editing)body.verificationNote=note;body.privacyConsent=data.get('privacyConsent')==='on';
  if(editing)body.revision=editing.revision;else body.requestId=requestId;
  busy=true;const b=form.querySelector('[type="submit"]');b.disabled=true;notice('검토 요청을 보내고 있습니다.');
  try{const authorToken=await ensureVisitor();await api('/api/tips'+(editing?'/'+editing.id:''),{method:editing?'PATCH':'POST',body,authenticated:true,authorToken});if(alive){mode='mine';editing=null;await load();notice('검토를 요청했습니다. 공개 전까지 내 제출 내역에서 상태를 확인할 수 있습니다.');}}catch(error){if(alive)notice(error.message,true);}finally{busy=false;if(b.isConnected)b.disabled=false;}
 }
 const change=event=>{if(event.target.closest('[data-tip-form]')&&!busy)requestId=requestUUID();if(event.target.dataset.tipFilter==='opponent'&&!busy){opponent=event.target.value;load();}};
 const input=event=>{if(event.target.closest('[data-tip-form]')&&!busy)requestId=requestUUID();};
 root.addEventListener('click',click);root.addEventListener('submit',submit);root.addEventListener('change',change);root.addEventListener('input',input);load();
 return ()=>{alive=false;++version;controllers.forEach(c=>c.abort());root.removeEventListener('click',click);root.removeEventListener('submit',submit);root.removeEventListener('change',change);root.removeEventListener('input',input);};
}
